/**
 * R1: substantive English–Tamil lessons for previously assessment-only
 * chapters in Units I and V. Academic/Tamil editorial acceptance is OPEN.
 * Original A5 assets remain unchanged and practice follows the lessons.
 * Image masters must be actual source files, never generated Compose geometry.
 */
internal object FiveUnitRestorationLessons {
    internal data class Chapter(
        val chapterId: String,
        val heading: BilingualText,
        val sections: List<NereisTextbookSection>,
    ) {
        init { require(sections.size >= 2) }
    }
    private fun b(en:String,ta:String)=BilingualText(en,ta)
    private fun s(id:String,en:String,ta:String,en1:String,ta1:String,en2:String,ta2:String)=
        NereisTextbookSection(id,b(en,ta),listOf(b(en1,ta1),b(en2,ta2)))
    val chapters: List<Chapter> = listOf(
        Chapter("u1-intro",b("Introduction to invertebrate zoology","முதுகெலும்பற்ற உயிரினங்கள் அறிமுகம்"),listOf(
            s("scope",
                "Scope and classification",
                "பரப்பும் வகைப்பாடும்",
                "Invertebrates are animals without a vertebral column, but they do not constitute a single natural taxonomic clade. The undergraduate syllabus groups diverse animal lineages for comparative anatomical teaching.",
                "முதுகெலும்புத் தூண் இல்லாத விலங்குகள் முதுகெலும்பற்றவை எனக் கற்பிக்கப்படுகின்றன. இவை ஒரே இயற்கை பரிணாமக் குழு அல்ல; பல்வேறு விலங்கு வழித்தோன்றல்கள் ஒப்பீட்டு உடற்கூறு ஆய்வுக்காக இணைக்கப்படுகின்றன.",
                "Study body symmetry, germ layers, coelomic organization, segmentation, feeding, excretion and reproductive patterns together with recognized phylogenetic relationships.",
                "சமச்சீர், கருவடுக்குகள், உடற்குழி அமைப்பு, உடற்கண்டப் பிரிவு, உணவூட்டம், கழிவுநீக்கம், இனப்பெருக்கம் ஆகியவற்றைப் பரிணாம உறவுகளுடன் ஒப்பிட்டுக் கற்க வேண்டும்."),
            s("evidence",
                "Observation and scientific naming",
                "காண்பும் அறிவியல் பெயரிடலும்",
                "A practical record must separate features actually visible in the specimen from structures inferred from a diagram or described by a textbook. Always name the magnification and specimen preparation when applicable.",
                "செய்முறைப் பதிவேட்டில் மாதிரியில் நேரடியாகக் காணப்படும் பண்புகளையும் பாடநூல் படத்தில் மட்டும் காட்டப்படும் அமைப்புகளையும் தெளிவாகப் பிரிக்க வேண்டும். பொருந்தும் இடத்தில் உருப்பெருக்கமும் தயாரிப்பு முறையும் குறிப்பிடப்பட வேண்டும்.",
                "Anatomical drawings must preserve relative organ placement and use unambiguous leader lines. Classical classifications should be labelled as historical conventions when modern phylogeny has changed them.",
                "உடற்கூறுப் படங்களில் உறுப்புகளின் ஒப்பீட்டு இடங்கள் சரியாக இருக்க வேண்டும்; குறிக்கோடுகள் குழப்பமின்றி முடிவடைய வேண்டும். பழைய வகைப்பாடுகளையும் நவீன இனவரலாற்று நிலைப்பாட்டையும் வேறுபடுத்திக் குறிப்பிட வேண்டும்."),
            s("scientific-classification",
                "From diagnostic characters to evolutionary classification",
                "அடையாளப் பண்புகளிலிருந்து பரிணாம வகைப்பாட்டிற்கு",
                "Identify an animal by comparing observed diagnostic characters against reliable descriptions. Species, genus, family, order, class, phylum and kingdom are nested conventional ranks. A binomial species name contains the genus followed by the specific epithet, rather than two independent classification ranks.",
                "உயிரினத்தை அடையாளம் காணப் பார்வையில் கண்ட வேறுபடுத்தும் பண்புகளை நம்பத்தகுந்த விளக்கங்களுடன் ஒப்பிட வேண்டும். இனம், பேரினம், குடும்பம், வரிசை, வகுப்பு, தொகுதி, உலகம் ஆகியவை அடுக்கமைந்த வகைப்பாட்டு நிலைகள். இருசொற் அறிவியல் பெயரில் பேரினப் பெயரைத் தொடர்ந்து இனச்சிறப்புப் பெயரடை வருகிறது; அவை இரண்டு தனி நிலைகள் அல்ல.",
                "Modern phylogenetic classification tests hypotheses of common ancestry using morphology, development and molecular sequences. Traditional syllabus groupings remain useful for exam comparison, but do not necessarily correspond to natural evolutionary clades.",
                "நவீன இனவரலாற்று வகைப்பாடு உடலமைப்பு, வளர்ச்சி, மூலக்கூறுத் தொடர்கள் ஆகியவற்றின் மூலம் பொதுமூதாதை குறித்த கருத்துகளைச் சோதிக்கிறது. பழைய பாடத்திட்டக் குழுப்பெயர்கள் தேர்வு ஒப்பீட்டிற்கு உதவினாலும் அவை அனைத்தும் இயற்கைப் பரிணாமக் கிளைகளாக இருக்க வேண்டியதில்லை.")
        )),
        Chapter("u1-protozoa",b("Protozoa: traditional classification and modern interpretation","புரோட்டோசோவா: மரபு வகைப்பாடும் நவீன விளக்கமும்"),listOf(
            s("classification",
                "Traditional classes and limitations",
                "பாரம்பரிய வகுப்புகளும் வரம்புகளும்",
                "Older syllabi divide protozoans by locomotory organs into Sarcodina, Mastigophora, Ciliata and Sporozoa. These are teaching categories, not equivalent branches of a single modern phylogenetic group.",
                "பழைய பாடத்திட்டங்களில் போலிக்கால்கள், கசையிழைகள், குறுஇழைகள் மற்றும் ஒட்டுண்ணித் தன்மையை அடிப்படையாகக் கொண்டு சார்கோடினா, மாஸ்டிகோபோரா, சிலியேட்டா, ஸ்போரோசோவா எனப் பிரிக்கின்றனர். இவை நவீன பரிணாமக் கிளைகளுக்கு நேரடியாகச் சமமானவை அல்ல.",
                "Paramecium is a ciliate, Entamoeba an amoebozoan, Trypanosoma and Leishmania kinetoplastids, and Plasmodium an apicomplexan. Their similarity as unicellular eukaryotes does not prove close evolutionary kinship.",
                "பாரமீசியம் குறுஇழையுயிரி; என்டமீபா அமீபோசோவா; டிரிப்பனோசோமா, லீஷ்மேனியா கைனெட்டோபிளாஸ்டிடுகள்; பிளாஸ்மோடியம் அபிகாம்ப்ளெக்சா. ஒருசெல் யூகேரியோட்டுகளாக இருப்பது மட்டுமே நெருங்கிய பரிணாம உறவை நிரூபிக்காது."),
            s("cell",
                "Cellular organization and reproduction",
                "செல்லமைப்பும் இனப்பெருக்கமும்",
                "Protozoan teaching examples commonly display a nucleus, food-uptake structures, motility systems and membrane-bound organelles, but no single example represents all protist cell architectures.",
                "பாடத்திட்டத்தில் எடுத்துக்காட்டாக உள்ள ஒருசெல் உயிரிகளில் உட்கரு, உணவெடுக்கும் அமைப்புகள், இயக்க உறுப்புகள், சவ்வால் சூழப்பட்ட உறுப்புகள் காணப்படலாம். ஒரு எடுத்துக்காட்டு எல்லா புரோட்டிஸ்ட் செல்களையும் பிரதிநிதித்துவப்படுத்தாது.",
                "Compare binary fission, multiple fission, encystment and sexual processes only in the organisms where they are documented. Distinguish infective stages from diagnostic stages in human parasites.",
                "இருகூறுபடுதல், பலகூறுபடுதல், சிஸ்ட் உருவாக்கம், பால்சார் நிகழ்வுகள் ஆகியவை எந்த உயிரியில் நிகழ்கின்றன என்பதைத் தனித்தனியாகக் கற்க வேண்டும். மனித ஒட்டுண்ணிகளில் தொற்றுநிலையையும் நோயறிதல் நிலையையும் பிரித்தறிய வேண்டும்."),
            s("historical-taxonomy",
                "Protozoa as a historical teaching assemblage",
                "புரோட்டோசோவா என்ற பாரம்பரியப் பாடப்பிரிவு",
                "Protozoa is a convenient historical grouping of many animal-like unicellular eukaryotes, not one universally accepted modern phylum. Amoeboid, ciliate, flagellate and apicomplexan forms belong to several different eukaryotic evolutionary lineages.",
                "புரோட்டோசோவா என்பது விலங்கு போன்ற பல ஒருசெல் மெய்க்கருவுயிரிகளுக்குப் பயன்படுத்தப்பட்ட பாரம்பரியப் பெயர்; அது நவீன வகைப்பாட்டில் ஏற்றுக்கொள்ளப்பட்ட ஒரே தொகுதி அல்ல. அமீபா போன்றவை, சிலியேட்டுகள், கசையிழை உயிரிகள், அபிகாம்ப்ளெக்ஸன்கள் வெவ்வேறு பரிணாமக் கிளைகளைச் சேர்ந்தவை.",
                "Free-living protists participate in microbial food webs and nutrient recycling; parasites may require distinct host or vector stages. Compare locomotion, feeding, nuclear organization and life cycles rather than describing every organism in this historical group as a primitive animal.",
                "சுதந்திரமாக வாழும் புரோட்டிஸ்டுகள் நுண்ணுயிர் உணவுவலையிலும் ஊட்டச்சத்துச் சுழற்சியிலும் பங்கு வகிக்கின்றன; ஒட்டுண்ணிகளுக்குக் குறிப்பிட்ட புரவலன் அல்லது கடத்தி நிலைகள் தேவைப்படலாம். இவற்றை எல்லாம் எளிய விலங்குகள் என்று அழைப்பதை விட இயக்கம், உணவூட்டம், உட்கருவமைப்பு, வாழ்க்கைச் சுழற்சி ஆகியவற்றை ஒப்பிட்டுக் கற்க வேண்டும்.")
        )),
        Chapter("u1-nutrition",b("Nutrition in protozoans","புரோட்டோசோவா உயிரிகளில் உணவூட்டம்"),listOf(
            s("pathways",
                "Holozoic, holophytic and absorptive nutrition",
                "விலங்குண்ணல், ஒளிச்சேர்க்கை, உறிஞ்சல்",
                "Paramecium uses a specialized oral apparatus to concentrate particulate food, form food vacuoles and digest contents intracellularly. Pseudopod-bearing amoebae may engulf particles by phagocytosis.",
                "பாரமீசியத்தில் வாய்ப்பள்ளமும் உணவெடுக்கும் உறுப்புகளும் உணவுத்துகள்களைச் சேர்த்து உணவுநுண்குமிழ்களை உருவாக்குகின்றன; செலுக்குள்ளேயே செரிமானம் நடைபெறுகிறது. அமீபாவில் போலிக்கால்கள் மூலம் துகள்களை விழுங்க முடியும்.",
                "Some photosynthetic protists synthesize organic matter while others absorb dissolved nutrients; these nutritional modes are not synonymous with modern zoological classes.",
                "சில ஒளிச்சேர்க்கை புரோட்டிஸ்டுகள் கரிம உணவைத் தயாரிக்கின்றன; மற்றவை கரைந்த ஊட்டச்சத்துகளை உறிஞ்சுகின்றன. இவ்வுணவு முறைகள் நவீன வகைப்பாட்டு வகுப்புகளுடன் நேரடியாக ஒத்துப்போவதில்லை."),
            s("digestion",
                "Food-vacuole formation and egestion",
                "உணவுநுண்குமிழ் உருவாக்கமும் வெளியேற்றமும்",
                "In ciliates, phagosome maturation involves fusion with digestive compartments, progressive acidification and recycling. Undigested residues leave through an organized egestion region in Paramecium.",
                "குறுஇழையுயிரிகளில் உணவுநுண்குமிழ்கள் செரிமானக் கூறுகளுடன் இணைந்து படிப்படியாக முதிர்ச்சி அடைகின்றன. பாரமீசியத்தில் செரியாத கழிவுகள் ஒழுங்கமைந்த கழிவுவெளியேற்றப் பகுதியில் வெளியேற்றப்படுகின்றன.",
                "A food vacuole is not the contractile vacuole: the former processes nutrients, whereas the latter regulates excess water. These structures must be separately identified in anatomical plates.",
                "உணவுநுண்குமிழும் சுருங்கும் நுண்குமிழும் ஒன்றல்ல. முதல் அமைப்பு உணவைச் செரிக்கிறது; இரண்டாவது நீர்ச் சமநிலையை ஒழுங்குபடுத்துகிறது. உடலமைப்புப் படத்தில் இரண்டையும் தனித்தனியாகக் காட்ட வேண்டும்."),
            s("nutrition-mechanisms",
                "Particle ingestion, dissolved food and phototrophy",
                "உணவுத் துகள்கள் உட்கொள்ளல், கரைசல் உறிஞ்சல், ஒளியுணவாக்கம்",
                "Holozoic feeding involves particle capture and internal digestion, often inside food vacuoles. Osmotrophic feeding takes up dissolved organic substances across a surface. Phototrophic protists use light energy to fix carbon; mixotrophs may combine nutrition strategies depending on the environment.",
                "ஹோலோசோயிக் உணவூட்டத்தில் உணவுத் துகள்கள் பிடிக்கப்பட்டு உணவுக் குமிழ்களுக்குள் செரிக்கப்படுகின்றன. ஆஸ்மோட்ரோஃபிக் முறையில் கரைந்த கரிமப் பொருட்கள் மேற்பரப்பு வழியாக உறிஞ்சப்படுகின்றன. ஒளியுணவாக்க உயிரிகள் ஒளி ஆற்றலால் கரிமப் பொருளை உருவாக்குகின்றன; மிக்சோட்ரோஃப்கள் சூழலுக்கேற்ப ஒன்றுக்கு மேற்பட்ட முறைகளை இணைக்கின்றன.",
                "Paramecium uses currents generated by oral cilia to guide food into its feeding apparatus, whereas Amoeba extends pseudopodia around particles. Many Euglena can photosynthesize and also utilize environmental organic compounds. Motility alone does not reliably determine nutritional type.",
                "பாரமீசியத்தில் வாய்ப்பகுதிக் குறுஇழைகள் உருவாக்கும் ஓட்டம் உணவை வாயமைப்பிற்கு இட்டுச் செல்கிறது; அமீபாவில் போலிக்கால்கள் துகள்களைச் சூழ்ந்து உட்கொள்கின்றன. பல யூக்ளீனாக்கள் ஒளிச்சேர்க்கை செய்வதுடன் வெளிப்புறக் கரிமப் பொருட்களையும் பயன்படுத்தக்கூடும். இயக்க வகையை மட்டும் கொண்டு ஊட்டமுறையை முடிவு செய்ய முடியாது.")
        )),
        Chapter("u1-host-parasite",b("Host–parasite interactions in protozoans","புரவலன்–ஒட்டுண்ணி உறவுகள்"),listOf(
            s("entamoeba",
                "Entamoeba: infection and disease",
                "என்டமீபா: தொற்றும் நோயியலும்",
                "Entamoeba histolytica is transmitted by ingestion of mature cysts from contaminated food or water. Trophozoites colonize the large intestine and may invade tissue in some infections.",
                "என்டமீபா ஹிஸ்டோலிட்டிகாவின் முதிர்ந்த சிஸ்டுகள் மாசடைந்த உணவு அல்லது நீர் மூலம் உடலுக்குள் செல்கின்றன. வளர் நிலைகள் பெருங்குடலில் வாழ்கின்றன; சில தொற்றுகளில் திசுக்களுக்குள் ஊடுருவலாம்.",
                "Morphology alone may not separate E. histolytica from E. dispar. Microscopy observations, diagnostic methods and the limits of the evidence should be explicitly distinguished.",
                "உருவ அமைப்பை மட்டும் கொண்டு E. histolytica மற்றும் E. dispar ஆகியவற்றை உறுதியாகப் பிரிக்க முடியாது. நுண்ணோக்கி காண்புகள், நோயறிதல் முறைகள், அவற்றின் வரம்புகள் ஆகியவற்றைப் பிரித்துக் கூற வேண்டும்."),
            s("plasmodium",
                "Plasmodium and the mosquito vector",
                "பிளாஸ்மோடியமும் கொசு கடத்தலும்",
                "In human malaria, an infected female Anopheles mosquito introduces sporozoites; liver development precedes repeated erythrocytic cycles. Sexual development and sporogony take place in the mosquito.",
                "மலேரியாவில் தொற்றுடைய பெண் அனாபிலிஸ் கொசு ஸ்போரோசோயிட்டுகளை உட்செலுத்துகிறது. கல்லீரல் வளர்ச்சியைத் தொடர்ந்து இரத்தச் சிவப்பணு சுழற்சிகள் நடைபெறுகின்றன. பால்சார் வளர்ச்சியும் ஸ்போராகனியும் கொசுவில் நிகழ்கின்றன.",
                "Liver hypnozoites are associated with P. vivax and P. ovale, not P. falciparum. Any life-cycle figure must identify its species scope and correctly mark infective stages.",
                "கல்லீரல் உறக்க ஹிப்னோசோயிட்கள் P. vivax மற்றும் P. ovale ஆகியவற்றுடன் தொடர்புடையவை; P. falciparum இல் அவை இல்லை. வாழ்க்கைச் சுழற்சிப் படம் எந்த இனத்தைச் சுட்டுகிறது என்பதைத் தெளிவாகக் குறிப்பிட வேண்டும்."),
            s("contrast-infective-stages",
                "Entamoeba and Plasmodium: distinct routes of infection",
                "என்டமீபா, பிளாஸ்மோடியம்: மாறுபட்ட தொற்று வழிகள்",
                "Entamoeba histolytica is commonly transmitted when a mature cyst is swallowed with contaminated food or water. Excystation produces trophozoites in the intestine, and cysts shed in faeces support onward transmission. Some infections remain intestinal, while invasive disease can affect the colon and liver.",
                "என்டமீபா ஹிஸ்டோலிட்டிகா பொதுவாக மாசடைந்த உணவு அல்லது நீரில் உள்ள முதிர்ந்த சிஸ்டை விழுங்குவதால் பரவுகிறது. குடலில் சிஸ்ட் உறைநீங்கி வளர் நிலைகள் உருவாகின்றன; மலத்துடன் வெளியேறும் சிஸ்டுகள் தொற்றைப் பரப்புகின்றன. சில தொற்றுகள் குடலிலேயே இருந்தாலும் ஊடுருவும் நோய் பெருங்குடலையும் கல்லீரலையும் பாதிக்கலாம்.",
                "An infected female Anopheles mosquito inoculates Plasmodium sporozoites during biting. Asexual development takes place in the human liver and blood, whereas fertilization and subsequent sexual development occur in the mosquito. The mosquito is the definitive host in the classical sexual-reproduction sense; these parasites do not share an infective stage.",
                "தொற்றுடைய பெண் அனாபிலிஸ் கொசு கடிக்கும்போது பிளாஸ்மோடியத்தின் ஸ்போரோசோயிட்டுகளை உட்செலுத்துகிறது. மனிதரின் கல்லீரலிலும் இரத்தத்திலும் பாலிலாப் பெருக்கம் நடைபெறுகிறது; பாலணு இணைவும் அடுத்த பாலின வளர்ச்சியும் கொசுவில் நிகழ்கின்றன. ஆகவே பாலினப்பெருக்க அடிப்படையில் கொசு இறுதிப் புரவலன்; இரு ஒட்டுண்ணிகளுக்கும் ஒரே தொற்றுநிலை கிடையாது.")
        )),
        Chapter("u1-locomotion",b("Locomotion in protozoan teaching organisms","புரோட்டோசோவா உயிரிகளின் இயக்கம்"),listOf(
            s("organelles",
                "Pseudopodia, flagella and cilia",
                "போலிக்கால்கள், கசையிழைகள், குறுஇழைகள்",
                "Amoeboid crawling involves actin-dependent cell-shape changes and transient pseudopodia. Flagellate swimming is driven by coordinated axonemal bending; ciliates coordinate numerous shorter cilia.",
                "அமீபா இயக்கத்தில் ஆக்டின் சார்ந்த செல்வடிவ மாற்றங்களும் தற்காலிக போலிக்கால்களும் பங்கேற்கின்றன. கசையிழை அசைவில் ஆக்சோநீமின் வளைவும் குறுஇழையுயிரிகளில் பல குறுஇழைகளின் ஒத்திசைவும் செயல்படுகின்றன.",
                "The traditional locomotory grouping can aid microscope recognition but does not provide reliable phylogenetic classification. Apicomplexan gliding is fundamentally different from ciliary swimming.",
                "மரபு இயக்க அடிப்படையிலான பிரிவு நுண்ணோக்கி அடையாளத்திற்கு உதவலாம்; ஆனால் பரிணாம வகைப்பாட்டுக்கு போதாது. அபிகாம்ப்ளெக்சா வழுக்கிச் செல்லும் இயக்கம் குறுஇழை நீச்சலிலிருந்து மாறுபடுகிறது."),
            s("paramecium",
                "Metachronal waves and avoiding response",
                "மெட்டாக்ரோனல் அலைகளும் தடைத்தவிர்ப்பும்",
                "Paramecium cilia beat in coordinated metachronal waves. Changes in membrane electrical activity alter beating direction and support transient reversal during an avoidance response.",
                "பாரமீசியக் குறுஇழைகள் மெட்டாக்ரோனல் அலைகளாக ஒத்திசைந்து அசைகின்றன. செல் சவ்வின் மின்செயல்பாட்டில் ஏற்படும் மாற்றம் அசைவின் திசையை மாற்றி தடைத்தவிர்ப்பை ஏற்படுத்தலாம்.",
                "In practical demonstrations, distinguish a visible swimming path from inferred ciliary beat mechanics. A still pencil plate can show direction arrows but cannot by itself establish movement rate.",
                "செய்முறை ஆய்வில் நேரடியாகக் காணப்படும் நீச்சல்பாதையையும் விளக்கமாக ஊகிக்கப்படும் குறுஇழை இயக்க முறையையும் வேறுபடுத்த வேண்டும். நிலைப்படம் திசையைக் காட்டலாம்; இயக்க வேகத்தை நிரூபிக்காது."),
            s("locomotion-mechanisms",
                "Cilia, flagella and pseudopodia: mechanisms and limits",
                "குறுஇழை, கசையிழை, போலிக்கால்: இயக்க செயல்முறைகள்",
                "Numerous short cilia beat with coordinated effective and recovery strokes, while longer eukaryotic flagella use bending waves to propel cells. Their usual motile axoneme has nine peripheral microtubule doublets and a central pair; the anchoring basal body instead commonly contains nine triplets.",
                "பல சிறிய குறுஇழைகள் செயலடி, மீட்படி அசைவுகளை ஒருங்கிணைத்து இயக்கத்தை உருவாக்குகின்றன; நீண்ட மெய்க்கருவுயிர்க் கசையிழைகளின் வளைவு அலைகள் செல்களை முன்னேற்றுகின்றன. இயங்கும் உள்இழை அமைப்பில் பொதுவாக ஒன்பது இரட்டைக் நுண்குழல்களும் மையத்தில் ஓர் இணையும் உள்ளன; அடித்தள உடலில் ஒன்பது மூன்றடுக்குத் தொகுதிகள் காணப்படும்.",
                "Pseudopodia form by local actin-dependent deformation of cytoplasm and membrane, allowing crawling and particle engulfment. Visible swimming or creeping can be described with a light microscope, but detailed axonemal ultrastructure requires higher-resolution evidence.",
                "போலிக்கால்கள் ஆக்டினைச் சார்ந்த சைட்டோபிளாசம், சவ்வு மாற்றங்களால் உருவாகி ஊர்வதற்கும் உணவுத் துகள்களைச் சூழ்வதற்கும் உதவுகின்றன. நீந்துதல் அல்லது ஊர்தலை ஒளி நுண்ணோக்கியில் விவரிக்கலாம்; நுண்குழல்களின் மிகநுண் அமைப்பை உறுதிப்படுத்த அதிகத் தெளிவுள்ள ஆய்வு தேவை.")
        )),
        Chapter("u5-mollusca",b("Mollusca: body plan and classification","மெல்லுடலிகள்: உடற்கூறும் வகைப்பாடும்"),listOf(
            s("plan",
                "Mantle, muscular foot and visceral mass",
                "மேன்டில், தசைப்பாதம், உள்ளுறுப்புத் தொகுதி",
                "Molluscs typically possess a mantle, a muscular foot and a visceral mass; many secrete a calcium-carbonate shell. Their structures vary widely among gastropods, bivalves and cephalopods.",
                "மெல்லுடலிகளில் பொதுவாக மேன்டில், தசைப்பாதம் மற்றும் உள்ளுறுப்புத் தொகுதி காணப்படும்; பல இனங்களில் கால்சியம் கார்பனேட் ஓடு சுரக்கப்படுகிறது. வயிற்றுக்காலிகள், இருமடிப்போடுகள், தலைக்காலிகள் ஆகியவற்றில் இவை மாறுபடுகின்றன.",
                "A radula is common among many molluscs but absent in bivalves. Respiratory structures include ctenidia and modified pulmonary cavities, and should never be drawn as universal molluscan organs.",
                "பல மெல்லுடலிகளில் ரேடுலா காணப்பட்டாலும் இருமடிப்போடுகளில் அது இல்லை. சுவாச அமைப்புகளாக சீனிடியா, மாற்றிய நுரையீரல் அறைகள் ஆகியவை காணப்படலாம்; இவை அனைத்திற்கும் பொதுவானவை என வரையக் கூடாது."),
            s("groups",
                "Major classes and adaptations",
                "முக்கிய வகுப்புகளும் தகவமைப்புகளும்",
                "Traditional teaching compares Gastropoda, Bivalvia, Polyplacophora, Scaphopoda and Cephalopoda by shell arrangement, foot modification, feeding and nervous-system development.",
                "பாரம்பரியப் பாடங்களில் கேஸ்ட்ரோபோடா, பைவால்வியா, பாலிபிளாகோபோரா, ஸ்காபோபோடா, செஃபலோபோடா ஆகியவற்றை ஓடு, பாதம், உணவெடுப்பு, நரம்பமைப்பு அடிப்படையில் ஒப்பிடுகின்றனர்.",
                "Use Pila for an operculate freshwater gastropod type study, not as a model for every marine or terrestrial snail. Record the specimen orientation before applying anatomical labels.",
                "மூடியுடைய நன்னீர் வயிற்றுக்காலிக்கான எடுத்துக்காட்டாக பைலாவைப் பயன்படுத்தலாம்; எல்லா நத்தைகளுக்கும் இது ஒரே மாதிரி அல்ல. உறுப்புக் குறியீடுகளுக்கு முன் மாதிரியின் திசைநிலையைக் குறிப்பிட வேண்டும்."),
            s("class-comparison",
                "How molluscan classes differ in form and function",
                "மெல்லுடலி வகுப்புகளின் உடலமைப்பு, செயல்பாட்டு வேறுபாடுகள்",
                "Gastropods commonly possess a creeping foot and may have a coiled shell; bivalves have two shell valves and often feed by filtration using gills. Cephalopods possess a funnel, modified arms and active predatory behavior. Chitons have eight dorsal plates, while scaphopods possess a tubular tusk-shaped shell.",
                "வயிற்றுக்காலிகளில் ஊரும் தசைப்பாதமும் பலவற்றில் சுருண்ட ஓடும் காணப்படும்; இருமடிப்போடுகளில் இரு ஓட்டுமடிப்புகளும் செவுள் வழி வடிகட்டி உணவெடுத்தலும் பொதுவாக உள்ளன. தலைக்காலிகளில் புனல், மாற்றமடைந்த கரங்கள், வேட்டையாடும் பழக்கம் காணப்படும். கைட்டன்களில் முதுகில் எட்டு ஓட்டுத்தகடுகள்; ஸ்காபோபோடுகளில் நீண்ட குழாய்போன்ற ஓடு காணப்படும்.",
                "The mantle usually secretes shell materials in shelled molluscs, but some lineages have reduced or lost shells. Classification must examine the foot, mantle cavity, radula or its absence, respiratory structures and development rather than relying on shell shape alone.",
                "ஓடு கொண்ட மெல்லுடலிகளில் மேன்டில் அதன் பொருட்களைச் சுரக்கிறது; சில குழுக்களில் ஓடு குறைந்தோ மறைந்தோ உள்ளது. வகைப்பாட்டிற்கு ஓட்டின் வடிவம் மட்டும் போதாது; பாதம், மேன்டில் அறை, ரேடுலா இருப்பு அல்லது இல்லாமை, சுவாச அமைப்பு, வளர்ச்சி ஆகியவற்றையும் ஆய்வு செய்ய வேண்டும்.")
        )),
        Chapter("u5-pila",b("Pila: detailed freshwater gastropod type study","பைலா: நன்னீர் நத்தை இன ஆய்வு"),listOf(
            s("external",
                "Shell, operculum and head-foot",
                "ஓடு, ஓடுமூடி, தலை–பாதம்",
                "Pila has a coiled shell with an apex, spire, body whorl, aperture and operculum. The broad muscular foot enables crawling; the head bears tentacles, eyes and the mouth.",
                "பைலாவில் உச்சி, சுருள், உடற்சுருள், திறப்பு, ஓடுமூடி உடைய சுருண்ட ஓடு காணப்படும். அகன்ற தசைப்பாதம் ஊர்வதற்கு உதவுகிறது; தலையில் உணர்கொம்புகள், கண்கள், வாய் ஆகியவை உள்ளன.",
                "In a record plate, separate shell morphology from the dissected soft body. Label columella, suture and the position of the operculum only where actually visible.",
                "செய்முறைப் படத்தில் ஓட்டின் புற அமைப்பையும் பிரித்துக் காட்டப்பட்ட மென் உடலையும் தனித்தனியாக வரைய வேண்டும். கொலுமெல்லா, சுருள் தையல், ஓடுமூடியின் இடம் ஆகியவற்றைத் தெளிவாகக் குறிக்க வேண்டும்."),
            s("mantle",
                "Mantle cavity, ctenidium and pulmonary sac",
                "மேன்டில் அறை, சீனிடியம், நுரையீரல் பை",
                "Pila is adapted for aquatic and aerial gas exchange. The mantle cavity contains a ctenidium and a pulmonary region, together with openings and pallial structures requiring careful spatial distinction.",
                "பைலா நீரிலும் காற்றிலும் சுவாசிக்கும் வகையில் தகவமைந்துள்ளது. மேன்டில் அறையில் சீனிடியம், நுரையீரல் பகுதி மற்றும் தொடர்புடைய திறப்புகள் உள்ளன; அவற்றின் இடங்களைத் தெளிவாக வேறுபடுத்த வேண்டும்.",
                "Do not confuse the ctenidium with the osphradium, a sensory organ near the branchial region. A scientific plate must distinguish mantle fold, vascular respiratory surface and branchial water route.",
                "சீனிடியத்தை அதன் அருகிலுள்ள உணர்வுறுப்பான ஆஸ்ப்ரேடியத்துடன் குழப்பக் கூடாது. மேன்டில் மடிப்பு, இரத்தநாளம் கொண்ட சுவாச மேற்பரப்பு, நீர் செல்லும் பாதை ஆகியவற்றைத் தனித்தனியாகக் காட்ட வேண்டும்."),
            s("organs",
                "Feeding, circulation, excretion and reproduction",
                "உணவூட்டம், சுற்றோட்டம், கழிவுநீக்கம், இனப்பெருக்கம்",
                "The buccal mass houses a radula used for scraping food. The digestive tract connects to digestive gland tissue; the heart and kidney are located in the visceral complex.",
                "வாய்த்தசைத் தொகுதியில் உணவை உரிக்கும் ரேடுலா உள்ளது. செரிமானக் குழாய் செரிமானச் சுரப்பியுடன் தொடர்புடையது; இதயமும் சிறுநீரகமும் உள்ளுறுப்புத் தொகுதியில் அமைந்துள்ளன.",
                "Pila is dioecious; male and female reproductive ducts should be studied separately. It is incorrect to place both complete reproductive systems in one generalized adult specimen drawing.",
                "பைலாவில் ஆண், பெண் தனித்தனியானவை. இனப்பெருக்கக் குழாய்களை ஆண் மற்றும் பெண் மாதிரிகளில் தனியாகக் கற்க வேண்டும். ஒரு பொதுவான முதிர்ந்த உயிரி படத்தில் இருபாலின முழு அமைப்பையும் சேர்த்துக் காட்டக் கூடாது."),
            s("dual-respiration",
                "Aquatic and aerial respiration: functional comparison",
                "நீர்ச் சுவாசமும் காற்றுச் சுவாசமும்: செயற்பாட்டு ஒப்பீடு",
                "In water, the ctenidium provides a vascular respiratory surface across which dissolved oxygen can diffuse into the blood. The mantle cavity also contains a pulmonary sac that permits air breathing when the animal has access to atmospheric air. The relative use of these surfaces depends on water conditions and the animal's behaviour.",
                "நீரில் கரைந்த ஆக்சிஜன், இரத்தநாளங்கள் நிறைந்த சீனிடியம் வழியாக இரத்தத்திற்குப் பரவுகிறது. மேன்டில் அறையிலுள்ள நுரையீரல் பை, வளிமண்டலக் காற்றை அணுகும் போது காற்றுச் சுவாசத்திற்கும் உதவுகிறது. எந்தச் சுவாச மேற்பரப்பு அதிகம் பயன்படுகிறது என்பது நீரின் நிலை மற்றும் உயிரியின் நடத்தையைப் பொறுத்து மாறும்.",
                "The osphradium is a sensory structure and should not be labelled as a gill. The nuchal lobes and mantle opening are relevant to the direction of respiratory currents. In an anatomical diagram, distinguish the gill lamellae, pulmonary roof and mantle cavity rather than drawing them as a single undivided chamber.",
                "ஆஸ்ப்ரேடியம் ஓர் உணர்வுறுப்பு; அதைச் செவுள் எனக் குறிக்கக் கூடாது. கழுத்து மடிப்புகளும் மேன்டில் திறப்பும் சுவாச நீரோட்டத்தின் திசையுடன் தொடர்புடையவை. உடற்கூறுப் படத்தில் செவுள் தகடுகள், நுரையீரல் பையின் கூரை, மேன்டில் அறை ஆகியவற்றை ஒரே பிரிவற்ற அறையாகக் காட்டாமல் தனித்தனியாகக் குறிக்க வேண்டும்.")
        )),
        Chapter("u5-torsion",b("Gastropod torsion and asymmetry","வயிற்றுக்காலிகளில் முறுக்கமும் அசமச்சீரும்"),listOf(
            s("process",
                "Developmental torsion",
                "வளர்ச்சிக் கால முறுக்கம்",
                "Gastropod torsion is a developmental rotation of the visceral mass, mantle and shell region relative to the head-foot. It relocates the mantle cavity and related organs toward the anterior in many lineages.",
                "வயிற்றுக்காலிகளில் முறுக்கம் என்பது தலை–பாதத்துடன் ஒப்பிடும்போது உள்ளுறுப்புத் தொகுதி, மேன்டில், ஓடு பகுதி வளர்ச்சியில் சுழல்வதாகும். இதனால் பல குழுக்களில் மேன்டில் அறை முன்புறம் நகர்கிறது.",
                "Torsion must not be confused with coiling of the shell: the two processes have distinct developmental meanings. Some opisthobranch lineages show partial or extensive secondary detorsion.",
                "முறுக்கத்தையும் ஓடு சுருள்வதையும் ஒன்றாகக் கருதக் கூடாது; இரண்டிற்கும் தனித்த வளர்ச்சிப் பொருள் உள்ளது. சில குழுக்களில் இரண்டாம் நிலை முறுக்கநீக்கம் காணப்படலாம்."),
            s("effects",
                "Anatomical consequences",
                "உடற்கூறியல் விளைவுகள்",
                "Classical teaching uses the crossing of certain visceral nerve connections as one consequence of torsion, although nerve organization has diversified extensively among extant gastropods.",
                "முறுக்கத்தின் விளைவாக சில உட்புற நரம்பு இணைப்புகள் குறுக்காக அமைவது மரபுப் பாடங்களில் குறிப்பிடப்படுகிறது. ஆனால் வாழும் வயிற்றுக்காலிகளில் நரம்பமைப்பு பல்வேறு மாற்றங்களைக் கண்டுள்ளது.",
                "A correct teaching sequence shows larval orientation before rotation, intermediate rotation and the resulting position of the mantle opening. Avoid portraying one simplified scheme as universal.",
                "சரியான பாட வரிசையில் முறுக்கத்திற்கு முன் இளம் நிலை, இடைநிலைச் சுழற்சி, அதன் பின் மேன்டில் திறப்பின் இடம் ஆகியவை காட்டப்பட வேண்டும். எளிய ஒரு மாதிரியையே அனைத்துக்கும் பொதுவானதாகக் கருதக் கூடாது."),
            s("sequence-and-implications",
                "Rotation sequence, sanitation and adaptive interpretations",
                "சுழற்சி வரிசை, கழிவுநீக்கம் மற்றும் தகவமைப்பு விளக்கங்கள்",
                "In the familiar textbook model of a prosobranch gastropod, the mantle cavity starts behind the head-foot and is carried toward the anterior during larval torsion, often described as an approximately 180-degree rotation. The position of the anus, ctenidia and mantle opening changes with the visceral complex; actual developmental timing and degree of rotation vary among taxa.",
                "மரபுப் பாடநூல் மாதிரியில் வயிற்றுக்காலியின் மேன்டில் அறை முதலில் தலை–பாதத்தின் பின்புறத்தில் உள்ளது. இளம்பருவ முறுக்கத்தின் போது உள்ளுறுப்புத் தொகுதி சுமார் 180 பாகை வரை சுழன்று மேன்டில் அறையை முன்புறம் கொண்டுவரலாம். இதனுடன் மலவாய், செவுள் (க்டெனிடியம்), மேன்டில் திறப்பு ஆகியவற்றின் சார்பு இடங்களும் மாறுகின்றன; சுழற்சியின் காலமும் அளவும் உயிரினக் குழுவைப் பொறுத்து மாறுபடும்.",
                "An anterior mantle cavity creates a potential fouling problem when exhalant water or waste passes near the head. Water-current routing, shell and mantle organization, and secondary anatomical changes help reduce this risk in different gastropods. Proposed evolutionary benefits of torsion remain hypotheses rather than experimentally established universal causes; torsion is not the same process as shell coiling.",
                "மேன்டில் அறை முன்புறம் வரும்போது வெளியேறும் நீரும் கழிவும் தலைக்கு அருகே செல்லும் வாய்ப்பு இருப்பதால் கழிவு மாசுபாட்டுச் சிக்கல் எழலாம். நீரோட்டத்தின் திசை, மேன்டில் அமைப்பு, பிற உடற்கூறு மாற்றங்கள் பல வயிற்றுக்காலிகளில் இச்சிக்கலைக் குறைக்க உதவுகின்றன. முறுக்கத்தின் பரிணாமப் பயன் குறித்த விளக்கங்கள் எல்லா இனங்களுக்கும் நிரூபிக்கப்பட்ட ஒரே காரணமாகக் கருதப்படக் கூடாது; முறுக்கம் என்பது ஓடு சுருள்வதிலிருந்து வேறுபட்டது.")
        )),
        Chapter("u5-pearl",b("Pearl formation and pearl culture","முத்து உருவாக்கமும் முத்து வளர்ப்பும்"),listOf(
            s("formation",
                "Mantle epithelial response",
                "மேன்டில் மேல்தோலின் செயல்",
                "Natural pearls form when mantle-derived epithelial tissue deposits successive organic and mineral layers around a nucleus or within a pearl sac. Nacre consists largely of aragonite crystals and organic matrix.",
                "மேன்டில் தொடர்புடைய மேல்தோல் திசு ஒரு மையத்தைச் சுற்றியோ முத்துப் பைக்குள்ளோ கரிம, கனிம அடுக்குகளைச் சுரப்பதால் இயற்கை முத்து உருவாகிறது. முத்தின் ஒளிர் அடுக்கில் அரகோனைட் படிகங்களும் கரிமப் பொருளும் முக்கியமானவை.",
                "Most commercial marine cultured pearls involve pearl oysters, which are bivalves, not the freshwater gastropod Pila. The organisms and culture methods must not be interchanged.",
                "வணிகக் கடல் முத்து வளர்ப்பில் பெரும்பாலும் இருமடிப்போடு முத்துச் சிப்பிகள் பயன்படுத்தப்படுகின்றன; நன்னீர் நத்தையான பைலா அல்ல. உயிரிகளையும் வளர்ப்பு முறைகளையும் குழப்பக் கூடாது."),
            s("culture",
                "Culture operations and environmental care",
                "வளர்ப்பு முறைகளும் சுற்றுச்சூழல் கவனமும்",
                "Cultured pearl production may use implantation of donor mantle tissue, sometimes with a bead nucleus, followed by suitable husbandry and monitoring. Procedures vary among marine and freshwater bivalves.",
                "வளர்ப்புமுத்து உற்பத்தியில் மேன்டில் திசு பொருத்துதல், சில முறைகளில் மணிமையம் சேர்த்தல், பின்னர் பொருத்தமான வளர்ப்புக் கவனிப்பு ஆகியவை இடம்பெறுகின்றன. கடல் மற்றும் நன்னீர் இருமடிப்போடுகளில் முறைகள் மாறுபடும்.",
                "Pearl quality depends on nacre deposition, health, environmental conditions and handling. Teaching material should discuss pollution, mortality and biodiversity impacts alongside economic value.",
                "முத்துத் தரம் ஒளிரடுக்கு படிதல், உடல்நலம், சுற்றுச்சூழல் நிலை, கையாளல் ஆகியவற்றைப் பொறுத்தது. பொருளாதார மதிப்புடன் மாசுபாடு, உயிரிழப்பு, உயிரினப் பல்வகைமை விளைவுகளையும் கற்பிக்க வேண்டும்."),
            s("pearl-sac-mechanism",
                "Pearl sac, nacre deposition and responsible culture",
                "முத்துப் பை, ஒளிரடுக்கு படிதல், பொறுப்பான வளர்ப்பு",
                "Pearl-oyster mantle epithelial tissue can form a pearl sac that deposits mineral and organic layers around a bead or other centre in cultivation. Nacre consists mainly of aragonite crystals and organic matrix. The old claim that all pearls arise simply from a grain of sand is biologically misleading.",
                "முத்துச் சிப்பியின் மேன்டில் மேல்தோல் திசு முத்துப் பையை உருவாக்கி, வளர்ப்பு முறைகளில் வைக்கப்படும் மணிமையம் போன்ற மையத்தைச் சுற்றிக் கனிம, கரிம அடுக்குகளைப் படியச் செய்கிறது. ஒளிரடுக்கு பெரும்பாலும் அரகோனைட் படிகங்களும் கரிமத் தளமும் கொண்டது. எல்லா முத்துகளும் மணல் துகள் ஒன்றால் மட்டுமே உருவாகின்றன என்ற கருத்து தவறாக வழிநடத்தும்.",
                "Marine bead-nucleated pearl culture commonly uses donor mantle graft tissue and subsequent careful husbandry; methods differ among bivalves. Discuss water quality, disease and ecological impact. The freshwater snail Pila must not be represented as a pearl oyster.",
                "கடல் மணிமைய வளர்ப்புமுத்தில் பொதுவாக மற்றொரு சிப்பியின் மேன்டில் திசு பொருத்தப்பட்டு கவனமாக வளர்க்கப்படுகிறது; இருமடிப்போடுகளுக்கு ஏற்ப முறைகள் மாறும். நீர்தரம், நோய், சூழலியல் பாதிப்பையும் விவாதிக்க வேண்டும். நன்னீர் நத்தையான பைலாவை முத்துச் சிப்பியாகக் காட்டக் கூடாது.")
        )),
        Chapter("u5-echinodermata",b("Echinodermata: classification and body plan","முள்தோலிகள்: வகைப்பாடும் உடற்கூறும்"),listOf(
            s("characters",
                "Pentamery, endoskeleton and coelom",
                "ஐந்தடுக்கு அமைப்பு, உட்கூடு, உடற்குழி",
                "Adult echinoderms generally display a pentaradial organization superimposed on an underlying bilateral ancestry. They have a calcareous endoskeleton of ossicles and a distinctive water-vascular system.",
                "முதிர்ந்த முள்தோலிகளில் பொதுவாக இருபக்கச் சமச்சீர் மூதாதைப் பின்னணியின் மீது ஐந்தாரச் சமச்சீர் அமைப்பு காணப்படுகிறது. கால்சியமுள்ள சிறு தகடுகளால் ஆன உட்கூடும் தனித்த நீர்க்குழாய் அமைப்பும் உள்ளன.",
                "The body is a deuterostome coelomate; free-swimming larvae are often bilaterally symmetrical. Avoid labeling adult starfish orientation as dorsal and ventral without defining oral and aboral surfaces.",
                "இவை இரண்டாம்வாயுயிரிகளும் உண்மையான உடற்குழி உடையவையும் ஆகும்; பல நீந்தும் இளம் நிலைகள் இருபக்கச் சமச்சீருடன் காணப்படுகின்றன. நட்சத்திரமீனில் வாய்ப்புறம், எதிர்வாய்ப்புறம் என்பவற்றை முதலில் வரையறுக்க வேண்டும்."),
            s("classes",
                "Five familiar living classes",
                "வாழும் ஐந்து முக்கிய வகுப்புகள்",
                "The familiar extant classes are Asteroidea, Ophiuroidea, Echinoidea, Holothuroidea and Crinoidea. Compare the arms, ambulacral surfaces, body wall and feeding specializations in each.",
                "வாழும் முக்கிய வகுப்புகள் அஸ்டெராய்டியா, ஒஃபியூராய்டியா, எக்கினாய்டியா, ஹோலோதூராய்டியா, கிரினாய்டியா ஆகும். கரங்கள், அம்புலாக்ரல் பரப்புகள், உடற்சுவர், உணவெடுக்கும் சிறப்பியல்புகள் ஆகியவற்றை ஒப்பிட வேண்டும்.",
                "Pedicellariae and dermal branchiae occur in some groups but are not universal echinoderm characters. They should be labelled only in the correct organism and view.",
                "பெடிசெல்லேரியா, தோல்செவுள்கள் சில குழுக்களில் மட்டுமே காணப்படும்; எல்லா முள்தோலிகளுக்கும் பொதுவான பண்புகள் அல்ல. உரிய உயிரி, உரிய காட்சியில் மட்டுமே அவற்றைக் குறிக்க வேண்டும்.")
        )),
        Chapter("u5-asterias",b("Asterias: starfish type study","அஸ்டீரியாஸ்: நட்சத்திரமீன் இன ஆய்வு"),listOf(
            s("external",
                "Oral and aboral surfaces",
                "வாய்ப்புறமும் எதிர்வாய்ப்புறமும்",
                "Asterias is a five-armed sea star with a central disc. The aboral surface bears spines and the madreporite; the oral surface has the mouth, ambulacral grooves and tube feet.",
                "அஸ்டீரியாஸ் மையத் தட்டுடன் பொதுவாக ஐந்து கரங்கள் கொண்ட நட்சத்திரமீன். எதிர்வாய்ப்புறத்தில் முட்களும் மேட்ரிபோரைட்டும்; வாய்ப்புறத்தில் வாய், அம்புலாக்ரல் பள்ளங்கள், குழாய்க்கால்கள் காணப்படுகின்றன.",
                "Do not draw the madreporite at the tip of an arm or place the anus centrally on the oral surface. External and dissection plates require separate orientation labels.",
                "மேட்ரிபோரைட்டை கரமுனையில் வரையக் கூடாது; ஆசனவாயை வாய்ப்புற மையத்தில் காட்டக் கூடாது. புறத்தோற்றம், பிரித்தாய்வு படங்களுக்கு தனித்த திசைக் குறிப்பு அவசியம்."),
            s("water-vascular",
                "Water-vascular system and locomotion",
                "நீர்க்குழாய் அமைப்பும் இயக்கமும்",
                "The water-vascular system includes madreporite, stone canal, ring canal, radial canals, lateral branches, ampullae and podia. Hydraulic pressure changes cooperate with muscles in tube-foot movement.",
                "நீர்க்குழாய் அமைப்பில் மேட்ரிபோரைட், கற்குழாய், வளையக்குழாய், ஆரக்குழாய்கள், பக்கக் கிளைகள், ஆம்புல்லாக்கள், குழாய்க்கால்கள் உள்ளன. நீரழுத்த மாற்றமும் தசைச் செயலும் குழாய்க்கால் இயக்கத்தில் இணைகின்றன.",
                "The stone canal connects the madreporite region to the ring canal; a radial canal runs along each arm. Leaders must end on these distinct structures, not on adjacent digestive branches.",
                "கற்குழாய் மேட்ரிபோரைட் பகுதியை வளையக்குழாயுடன் இணைக்கிறது; ஒவ்வொரு கரத்திலும் ஆரக்குழாய் நீள்கிறது. குறிக்கோடுகள் இவ்வேறுபட்ட அமைப்புகளிலேயே முடிவடைய வேண்டும்; அருகிலுள்ள செரிமானக் கிளைகளில் அல்ல."),
            s("internal",
                "Digestion and reproduction",
                "செரிமானமும் இனப்பெருக்கமும்",
                "The cardiac stomach can be everted during feeding; pyloric caeca extend into the arms and contribute to digestion. Gonads also extend into arms but are not digestive glands.",
                "உணவெடுக்கும் போது கார்டியாக் இரைப்பை வெளியே நீளக்கூடும்; பைலோரிக் குடற்பைகள் கரங்களுக்குள் நீண்டு செரிமானத்தில் பங்கேற்கின்றன. இனச்சுரப்பிகளும் கரங்களுக்குள் இருந்தாலும் அவை செரிமானச் சுரப்பிகள் அல்ல.",
                "Asterias commonly releases gametes into seawater, with external fertilization and planktonic development. Keep male and female gonad depiction consistent with the specimen and plate caption.",
                "அஸ்டீரியாஸ் பொதுவாக இனச்செல்களை கடல்நீரில் விடுகிறது; வெளிக்கருவுறுதலும் நீந்தும் இளம் நிலைகளும் காணப்படும். ஆண், பெண் இனச்சுரப்பிகளைக் காட்டும்போது மாதிரியும் படக்குறிப்பும் ஒன்றுக்கொன்று பொருந்த வேண்டும்.")
        )),
        Chapter("u5-echino-larvae",b("Echinoderm larval forms","முள்தோலிகளின் இளம்பருவ வடிவங்கள்"),listOf(
            s("types",
                "Bipinnaria, brachiolaria and other larvae",
                "பைபின்னாரியா, பிராக்கியோலாரியா மற்றும் பிற இளம் நிலைகள்",
                "Asteroid larvae commonly include bipinnaria and brachiolaria stages, whose ciliated bands and attachment structures differ. Asterias larval illustrations should not be substituted with an echinoid pluteus.",
                "நட்சத்திரமீன் வளர்ச்சியில் பைபின்னாரியா, பிராக்கியோலாரியா நிலைகள் காணப்படலாம்; சிலியப் பட்டைகளும் ஒட்டும் அமைப்புகளும் மாறுபடும். அஸ்டீரியாஸ் இளம் நிலைக்கு கடல்முள்ளியின் ப்ளூட்டியஸ் படத்தை மாற்றாகப் பயன்படுத்தக் கூடாது.",
                "Echinoids and ophiuroids have characteristic pluteus forms, while holothuroids commonly show auricularia and doliolaria stages. Species and taxonomic differences matter.",
                "எக்கினாய்டுகள் மற்றும் ஒஃபியூராய்டுகளில் ப்ளூட்டியஸ் வடிவங்கள்; ஹோலோதூராய்டுகளில் ஆரிகுலாரியா, டோலியோலாரியா நிலைகள் காணப்படுகின்றன. இனம் மற்றும் வகைப்பாட்டைப் பொறுத்து வேறுபாடுகள் உண்டு."),
            s("metamorphosis",
                "Larval symmetry and metamorphosis",
                "இளம் நிலைச் சமச்சீரும் உருமாற்றமும்",
                "Bilateral larval symmetry and adult pentaradial organisation are distinct developmental configurations. Metamorphosis reorganises tissues and establishes the juvenile echinoderm body.",
                "இளம் நிலையில் இருபக்கச் சமச்சீரும் முதிர்நிலையில் ஐந்தாரச் சமச்சீரும் தனித்த வளர்ச்சி அமைப்புகள். உருமாற்றத்தில் திசுக்கள் மறுஒழுங்குபட்டு இளம் முள்தோலி உடல் உருவாகிறது.",
                "In a practical record, show ciliary-band positions and larval arms where appropriate; never imply that all echinoderms pass through every named larval type.",
                "செய்முறைப் படத்தில் உரிய இடங்களில் சிலியப் பட்டைகள், இளம் கரங்கள் ஆகியவற்றைக் காட்ட வேண்டும்; எல்லா முள்தோலிகளும் எல்லா பெயரிடப்பட்ட இளம் நிலைகளையும் கடக்கின்றன என்று கூறக் கூடாது.")
        )),
        Chapter("u5-echino-affinities",b("Echinoderm affinities and deuterostomes","முள்தோலிகளின் பரிணாம உறவுகள்"),listOf(
            s("deuterostomes",
                "Echinoderms and chordates",
                "முள்தோலிகளும் முதுகுநாணுயிரிகளும்",
                "Echinoderms and chordates belong to Deuterostomia, supported by molecular phylogeny and comparative embryology. Echinoderms are not direct ancestors of living chordates.",
                "முள்தோலிகளும் முதுகுநாணுயிரிகளும் டியூட்டரோஸ்டோமியா குழுவைச் சேர்ந்தவை; மரபணு உறவியல் ஆய்வும் ஒப்பீட்டு கருவளர்ச்சியும் இதை ஆதரிக்கின்றன. வாழும் முள்தோலிகள் முதுகுநாணுயிரிகளின் நேரடி மூதாதைகள் அல்ல.",
                "Hemichordates and echinoderms form Ambulacraria in widely accepted contemporary analyses. The older hemichordate–chordate analogies must be evaluated in a modern phylogenetic context.",
                "ஹெமிகோர்டேட்டுகளும் முள்தோலிகளும் நவீன ஆய்வுகளில் அம்புலாக்ரேரியா என்ற குழுவாகக் கருதப்படுகின்றன. பழைய ஒப்புமைகளை நவீன இனவரலாற்று சூழலில் மதிப்பிட வேண்டும்."),
            s("evidence",
                "Larval and molecular evidence",
                "இளம் நிலை மற்றும் மூலக்கூறு சான்றுகள்",
                "Bilateral echinoderm larvae help explain the evolutionary transformation toward radial adult bodies. Similar developmental features alone, however, cannot replace a well-supported phylogenetic tree.",
                "முள்தோலிகளின் இருபக்கச் சமச்சீர் இளம் நிலைகள் முதிர்நிலையின் ஆரச் சமச்சீர் உருவாக்கத்தைப் புரிந்துகொள்ள உதவுகின்றன. ஒத்த கருவளர்ச்சி பண்புகள் மட்டும் இனவரலாற்று மரத்தை மாற்ற முடியாது.",
                "Discuss shared ancestry, convergent characters and secondary changes as separate hypotheses. Never present the traditional term 'connecting link' as proof of direct descent.",
                "பொது மூதாதை, ஒத்த இயல்பு தனித்த தோற்றம், இரண்டாம் நிலை மாற்றம் ஆகிய கருத்துக்களை வேறுபடுத்த வேண்டும். ‘இணைப்புயிரி’ என்ற பழைய சொல்லை நேரடி வம்சத் தோற்றச் சான்றாகக் கூறக் கூடாது.")
        )),
        Chapter("u5-fossils",b("Echinoderm fossils and geological significance","முள்தோலி தொல்லுயிர்களும் புவியியல் முக்கியத்துவமும்"),listOf(
            s("record",
                "Ossicles and fossil preservation",
                "உட்கூட்டுத் தகடுகளும் தொல்லுயிர் பாதுகாப்பும்",
                "Calcitic ossicles make many echinoderm groups valuable in the marine fossil record, although the articulated skeleton often disintegrates after death. Preservation depends on burial conditions.",
                "கால்சைட் தகடுகளால் ஆன உட்கூடு கடல் தொல்லுயிர் பதிவில் பல முள்தோலிக் குழுக்களை அடையாளம் காண உதவுகிறது. ஆனால் இறப்புக்குப் பின் இணைந்த தகடுகள் சிதறலாம்; பாதுகாப்பு புதைவு நிலைமையைப் பொறுத்தது.",
                "Crinoid columnals and echinoid tests are familiar fossils. Do not assign an isolated ossicle to a modern genus without diagnostic characters and stratigraphic support.",
                "கிரினாய்டு தண்டுத் தகடுகளும் எக்கினாய்டு ஓடுகளும் பரவலாக அறியப்பட்ட தொல்லுயிர்கள். தனித்த ஒரு தகட்டை போதுமான பண்புகள் இல்லாமல் நவீன பேரினமாக அடையாளம் காணக் கூடாது."),
            s("history",
                "Evolutionary and stratigraphic interpretation",
                "பரிணாமமும் அடுக்குப்பாறை விளக்கமும்",
                "Fossil echinoderms help reconstruct ancient marine habitats and changes in body organization through geological time. Extinct stem groups should not be forced into living class diagnoses.",
                "தொல்லுயிர் முள்தோலிகள் பழைய கடல் வாழிடங்களையும் புவியியல் காலங்களில் ஏற்பட்ட உடற்கூறு மாற்றங்களையும் மீட்டுருவாக்க உதவுகின்றன. அழிந்த குழுக்களை வாழும் வகுப்புகளுக்குள் வற்புறுத்திச் சேர்க்கக் கூடாது.",
                "When using a fossil sketch, annotate scale, preservation type, reliable taxonomic assignment and the locality or age if known. Art alone is not a substitute for specimen evidence.",
                "தொல்லுயிர் படத்தில் அளவுக்கோல், பாதுகாப்பு வகை, நம்பகமான வகைப்பாடு, தெரிந்தால் இடமும் காலமும் குறிப்பிடப்பட வேண்டும். வரைபடம் மட்டும் மாதிரி ஆதாரத்திற்குப் பதிலாகாது.")
        )),
        Chapter("u5-foot",b("Molluscan foot and locomotion","மெல்லுடலிகளின் பாதமும் இயக்கமும்"),listOf(
            s("variation",
                "Crawling, digging and attachment",
                "ஊர்தல், புதைத்தல், பற்றுதல்",
                "A gastropod uses waves of contraction along its muscular foot to crawl on mucus. Many bivalves have a wedge-shaped foot used for burrowing, whereas cephalopod locomotion is extensively modified.",
                "வயிற்றுக்காலி நத்தை அதன் தசைப்பாதத்தில் சுருக்க அலைகளை உருவாக்கி சளிப்பரப்பில் ஊர்கிறது. பல இருமடிப்போடுகளில் ஆப்புவடிவ பாதம் புதைய உதவுகிறது; தலைக்காலிகளில் அமைப்பு மிக மாற்றமடைந்துள்ளது.",
                "The cephalopod funnel and arms are associated with transformations of the molluscan head-foot complex. Do not depict them as an unmodified ventral crawling sole.",
                "தலைக்காலிகளின் புனலும் கரங்களும் மெல்லுடலியின் தலை–பாதத் தொகுதி மாற்றங்களுடன் தொடர்புடையவை. அவற்றை சாதாரண வயிற்றுப்புற ஊரும் பாதமாகக் காட்டக் கூடாது."),
            s("function",
                "Muscle, substrate and observation",
                "தசை, அடித்தளம், காண்பு",
                "Foot movement depends on muscular hydrostatic forces, adhesion and interaction with the substrate. Snails may alter pace and contact area in response to surface roughness and moisture.",
                "பாத இயக்கம் தசை நீரழுத்தம், ஒட்டுதல், அடித்தளத் தொடர்பு ஆகியவற்றைப் பொறுத்தது. பரப்பின் கரடுமுரடான தன்மை மற்றும் ஈரத்திற்கு ஏற்ப நத்தை இயக்கத்தை மாற்றலாம்.",
                "For a Pila practical plate, separate the broad creeping sole, operculum attachment and head tentacles. Do not confuse the foot with mantle lobes or the visceral mass.",
                "பைலா செய்முறைப் படத்தில் அகன்ற ஊரும் பாதம், ஓடுமூடி இணைப்பு, தலை உணர்கொம்புகள் ஆகியவற்றைத் தனித்தனியாகக் குறிக்க வேண்டும். பாதத்தையும் மேன்டில் மடிப்புகளையும் உள்ளுறுப்புத் தொகுதியையும் குழப்பக் கூடாது."),
            s("foot-modification",
                "Pila, Unio and cephalopods: modifications of the foot",
                "பைலா, யூனியோ, தலைக்காலிகள்: பாதத்தின் மாற்றங்கள்",
                "In Pila a broad muscular foot acts as a creeping sole; the operculum is borne on its posterior dorsal region. In Unio a compressed, wedge-shaped foot extends between shell valves for burrowing and anchorage. The paired shell valves are mantle derivatives, not parts of the foot.",
                "பைலாவில் அகன்ற தசைப்பாதம் பரப்பில் ஊர்வதற்குப் பயன்படுகிறது; அதன் பின்முதுகுப் பகுதியில் ஓடுமூடி உள்ளது. யூனியோவில் இரு ஓட்டுமடிப்புகளுக்கு இடையில் நீளும் ஆப்புவடிவத் தசைப்பாதம் புதைவதற்கும் பற்றுதலுக்கும் உதவுகிறது. இரு ஓட்டுமடிப்புகள் மேன்டில் உருவாக்கங்கள்; பாதத்தின் பகுதிகள் அல்ல.",
                "In cephalopods the ancestral foot region is reorganized into structures including the funnel and the appendage crown. The muscular funnel directs water expelled from the mantle cavity during jet propulsion. Compare function and homology; do not teach a flat creeping sole as universal for all molluscs.",
                "தலைக்காலிகளில் மூதாதைப் பாதப் பகுதி புனல் மற்றும் கரத்தொகுதி உள்ளிட்ட அமைப்புகளாக மறுஅமைந்துள்ளது. தசைமிகு புனல் மேன்டில் அறையிலிருந்து வெளியேறும் நீரைத் திசைமாற்றி நீர்பீச்சு இயக்கத்திற்கு உதவுகிறது. செயல்பாட்டையும் உறுப்பு உறவையும் ஒப்பிட வேண்டும்; தட்டையான ஊரும் பாதம் எல்லா மெல்லுடலிகளுக்கும் பொதுவானது அல்ல.")
        )),
        Chapter("u5-wvs",b("Water-vascular system of Asterias","அஸ்டீரியாஸின் நீர்க்குழாய் அமைப்பு"),listOf(
            s("route",
                "Madreporite to radial canal",
                "மேட்ரிபோரைட்டிலிருந்து ஆரக்குழாய் வரை",
                "The madreporite communicates through the stone canal with the ring canal around the mouth. Radial canals run into the arms, giving rise to lateral canals connected to individual tube-foot units.",
                "மேட்ரிபோரைட் கற்குழாய் வழியாக வாயைச் சுற்றியுள்ள வளையக்குழாயுடன் தொடர்பு கொள்கிறது. ஆரக்குழாய்கள் கரங்களுக்குள் நீண்டு ஒவ்வொரு குழாய்க்காலும் தொடர்புள்ள பக்கக் கால்வாய்களைத் தருகின்றன.",
                "A teaching drawing must trace the connected passages continuously; the ampulla is an internal bulb connected to a podium, not an independent external sensory tentacle.",
                "கற்பித்தல் படத்தில் தொடர்புடைய குழாய்கள் தொடர்ச்சியாகக் காட்டப்பட வேண்டும். ஆம்புல்லா என்பது குழாய்க்காலுடன் இணைந்த உள்ளகப் புடைப்பு; தனித்த வெளிப்புற உணர்கொம்பு அல்ல."),
            s("operation",
                "Ampullae, podia and hydraulic movement",
                "ஆம்புல்லா, குழாய்க்கால், நீரழுத்த இயக்கம்",
                "Tube feet extend and retract through coordinated fluid displacement and muscular activity. Adhesive mechanisms and substrate contact aid crawling, feeding and attachment.",
                "குழாய்க்கால்களின் நீட்டலும் சுருக்கமும் திரவ இடமாற்றம் மற்றும் தசைச் செயலால் ஒருங்கிணைகின்றன. ஒட்டுதல் மற்றும் அடித்தளத் தொடர்பு ஊர்தல், உணவெடுப்பு, பற்றுதல் ஆகியவற்றுக்கு உதவுகின்றன.",
                "For Asterias anatomy, a correct plate distinguishes ring canal, radial canal, lateral canal, ampulla, podium and associated Tiedemann bodies where visible. A schematic must not claim direct specimen accuracy.",
                "அஸ்டீரியாஸ் உடற்கூறில் வளையக்குழாய், ஆரக்குழாய், பக்கக்குழாய், ஆம்புல்லா, குழாய்க்கால், காணப்படும் டீடெமன் உடல்கள் ஆகியவை வேறுபடுத்தப்பட வேண்டும். பொதுப் படம் உண்மையான மாதிரி அளவீடாகக் கூறப்படக் கூடாது."),
            s("hydraulic-cycle",
                "Stepwise tube-foot extension, attachment and withdrawal",
                "குழாய்க்காலின் நீட்சி, பற்றுதல், மீட்சி: படிநிலைகள்",
                "When muscles surrounding an ampulla contract, fluid is displaced into its connected podium and the tube foot extends. The terminal disc contacts the substratum and can establish temporary adhesion using secreted adhesive substances; attachment is not adequately explained as simple suction in every sea star.",
                "ஆம்புல்லாவைச் சுற்றிய தசைகள் சுருங்கும்போது அதிலுள்ள திரவம் இணைந்த குழாய்க்காலுக்குள் செலுத்தப்படுகிறது; இதனால் குழாய்க்கால் நீள்கிறது. அதன் முனைவட்டு அடித்தளத்தைத் தொட்டு சுரக்கும் ஒட்டும் பொருட்களின் உதவியால் தற்காலிகப் பற்றுதலை ஏற்படுத்தலாம். எல்லா நட்சத்திரமீன்களிலும் பற்றுதல் வெறும் உறிஞ்சும் விசையால் மட்டுமே நிகழ்கிறது என்று கூறுவது சரியல்ல.",
                "Coordinated contractions of the podium and associated muscles, changes in fluid distribution, and controlled release of adhesion allow the foot to withdraw and move to a new position. Repeated cycles across many podia produce locomotion and help maintain grip during prey handling. The madreporite is not a pump that drives each individual step.",
                "குழாய்க்காலின் தசைச் சுருக்கம், திரவப் பகிர்வில் மாற்றம், ஒட்டுதலைக் கட்டுப்படுத்தி விடுவித்தல் ஆகியவை குழாய்க்காலை மீட்டு புதிய இடத்தில் வைக்க உதவுகின்றன. பல குழாய்க்கால்களின் ஒருங்கிணைந்த சுழற்சிகள் இடப்பெயர்ச்சிக்கும் இரையைக் கையாளும் போது பற்றுதலைப் பேணுவதற்கும் உதவுகின்றன. ஒவ்வொரு அடியையும் மேட்ரிபோரைட் தனியாகப் பம்ப் செய்து இயக்குவதில்லை."),
            s("system-organization",
                "Fluid pathways and anatomical distinctions",
                "திரவப் பாதைகளும் உடற்கூறு வேறுபாடுகளும்",
                "A typical pathway is madreporite, stone canal, circumoral ring canal, radial canals and lateral canals leading to ampullae and podia. The system contains coelomic fluid; it should not be represented as an open seawater pipe with unrestricted flow from the madreporite directly into every tube foot.",
                "வழக்கமான இணைப்புப் பாதை மேட்ரிபோரைட், கற்குழாய், வாயைச் சுற்றிய வளையக்குழாய், ஆரக்குழாய்கள், பக்கக்குழாய்கள், ஆம்புல்லா, குழாய்க்கால்கள் என்பதாகும். இவ்வமைப்பில் உடற்குழித் திரவம் உள்ளது; கடல்நீர் மேட்ரிபோரைட்டிலிருந்து ஒவ்வொரு குழாய்க்காலுக்கும் தடையின்றி நேரடியாகப் பாயும் திறந்த குழாயாக இதைக் காட்டக் கூடாது.",
                "Tiedemann bodies are associated with the ring canal, whereas Polian vesicles vary in presence and number across echinoderm groups and should not be added to an Asterias plate without species-specific evidence. Distinguish the internal ampulla from the external podium, and identify the ambulacral groove on the oral side of an arm.",
                "டீடெமன் உடல்கள் வளையக்குழாயுடன் தொடர்புடையவை. போலியன் பைகள் முள்தோலி குழுக்களிடையே இருப்பிலும் எண்ணிக்கையிலும் மாறுபடுவதால், இனத்திற்குரிய சான்றின்றி அஸ்டீரியாஸ் படத்தில் சேர்க்கக் கூடாது. உட்புற ஆம்புல்லாவையும் வெளிப்புறக் குழாய்க்காலையும் வேறுபடுத்தி, கரத்தின் வாய்ப்புறத்தில் உள்ள அம்புலாக்ரல் பள்ளத்தையும் அடையாளம் காண வேண்டும்.")
        )),
        Chapter("u5-cephalopods",b("Cephalopods: organization and adaptations","தலைக்காலிகள்: அமைப்பும் தகவமைப்புகளும்"),listOf(
            s("anatomy",
                "Arms, siphon and mantle",
                "கரங்கள், புனல், மேன்டில்",
                "Cephalopods include octopuses, squids, cuttlefishes and nautiluses. The muscular mantle assists ventilation and jet propulsion through the funnel, while arms or tentacles capture and manipulate food.",
                "தலைக்காலிகளில் ஆக்டோபஸ், ஸ்க்விட், கடில்ஃபிஷ், நாட்டிலஸ் ஆகியவை அடங்குகின்றன. தசைமிகு மேன்டில் சுவாசத்திற்கும் புனல் வழி நீர்த் தள்ளுதலுக்கும் உதவுகிறது; கரங்களும் நீள்கரங்களும் உணவைப் பிடிக்கின்றன.",
                "The shell is external in Nautilus, internalized or reduced in many coleoids, and absent in octopuses. A generalized shell-bearing mollusc figure therefore cannot represent every cephalopod.",
                "நாட்டிலஸில் ஓடு வெளிப்புறமாக உள்ளது; பல பிற தலைக்காலிகளில் அது உள்ளுறுப்பாகவோ குறைந்ததாகவோ உள்ளது; ஆக்டோபஸில் இல்லை. பொதுவான ஓடுடைய மெல்லுடலி படம் எல்லா தலைக்காலிகளையும் பிரதிநிதித்துவப்படுத்தாது."),
            s("physiology",
                "Sensory control and circulation",
                "உணர்வியல் கட்டுப்பாடும் சுற்றோட்டமும்",
                "Cephalopods possess well-developed eyes, elaborate nervous systems and closed circulatory systems with specialized hearts. Their complex behaviour should be studied as adaptation, not ranked intelligence.",
                "தலைக்காலிகளில் நன்கு வளர்ந்த கண்கள், சிக்கலான நரம்பமைப்பு, சிறப்பியல்புடைய இதயங்களைக் கொண்ட மூடிய சுற்றோட்ட அமைப்பு காணப்படுகிறது. நடத்தைத் திறன்களை தகவமைப்பாகக் கற்க வேண்டும்.",
                "Chromatophore organs contribute to rapid colour change in many coleoids. A practical illustration should separately label mantle, funnel, arms, gills and correctly identified reproductive structures.",
                "பல தலைக்காலிகளில் குரோமட்டோஃபோர் உறுப்புகள் விரைவான நிறமாற்றத்திற்கு உதவுகின்றன. செய்முறைப் படத்தில் மேன்டில், புனல், கரங்கள், செவுள்கள், உரிய இனப்பெருக்க உறுப்புகள் தனித்தனியாகக் குறிக்கப்பட வேண்டும்.")
        ))
    )
    val byId: Map<String,Chapter> = chapters.associateBy { it.chapterId }
    init {
        check(chapters.size == 17)
        check(byId.size == chapters.size)
        check(chapters.count { it.chapterId.startsWith("u1-") } == 5)
        check(chapters.count { it.chapterId.startsWith("u5-") } == 12)
    }
}
